+   * link), so the accessible name is exactly the product name — this test asserts the exact match
+   * again, not the looser leading-substring match the discovery temporarily required.
+   */
+  test('renders exactly one real, keyboard-reachable link, whose accessible name is exactly the product name', () => {
+    wrap(<ZimmProductCard {...buildCardProps('recentlyViewed')} />);
     const links = screen.getAllByRole('link');
     expect(links).toHaveLength(1);
-    expect(links[0]).toHaveAttribute('href', '/product/1');
+    expect(screen.getByRole('link', { name: 'Natura Dress' })).toHaveAttribute('href', '/product/1');
   });
 });

