/**
 * A complete, valid props object for a given variation — narrows on `variation` with a plain
 * `switch` (fine here: the "no switch/if on props.variation" constraint applies only to
 * index.tsx's own render body, not to test fixtures).
 *
 * Overloaded (not a single `(variation) => ZimmProductCardProps` signature) so a call site that
 * passes a literal (`buildCardProps('plp')`) gets back the properly *narrow* per-variation type,
 * not the full union — needed so a test can then add a variation-specific prop on top (e.g.
 * `{...buildCardProps('wishlist')} onRemove={fn}`) without TypeScript rejecting it as "not
 * present on every union member." A `test.each` call site passing a runtime (non-literal)
 * `variation` still resolves to the final, general overload below.
 */
function buildCardProps(variation: 'plp'): ZimmProductCardBaseProps & ZimmProductCardPlpVariation;
function buildCardProps(variation: 'home'): ZimmProductCardBaseProps & ZimmProductCardHomeVariation;
function buildCardProps(variation: 'wishlist'): ZimmProductCardBaseProps & ZimmProductCardWishlistVariation;
function buildCardProps(variation: 'recentlyViewed'): ZimmProductCardBaseProps & ZimmProductCardRecentlyViewedVariation;
function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps;
function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps {
  const base = {
    id: 'p1',
    href: '/product/1',
    name: 'Natura Dress',
    headingLevel: 'h3' as const,
    primaryImage: PRIMARY,
  };
  switch (variation) {
    case 'wishlist':
      return { ...base, variation, colour: 'Ivory', size: 'M', onRemove: vi.fn() };
    case 'home':
      return { ...base, variation };
    case 'plp':
      return { ...base, variation };
    case 'recentlyViewed':
      return { ...base, variation };
    default:
      // Exhaustiveness guard — a new union member without a matching branch here fails `tsc`,
      // not silently falls through to a wrong variation's shape.
      return ((): never => {
        throw new Error(`buildCardProps: unhandled variation ${JSON.stringify(variation)}`);
      })();
  }
}

describe('ZimmProductCardProps — discriminated union is enforced at compile time', () => {
  // Both cases below are type-only proof: `@ts-expect-error` makes `tsc --noEmit` fail this file
  // if the offending line does NOT produce a compile error (an "Unused '@ts-expect-error'
  // directive" diagnostic) — so these only stay green while the union genuinely rejects the
  // invalid shape. The runtime assertion is trivial; TypeScript strips the annotation either way,
  // so the object still constructs and runs at test time regardless of what `tsc` says about it.
  test('wishlist variation requires onRemove, colour and size (type-only)', () => {
    // @ts-expect-error — wishlist requires onRemove, colour and size; none are supplied here.
    const invalid: ZimmProductCardProps = {
      id: 'p1',
      href: '/product/1',
      name: 'Dress',
      headingLevel: 'h3',
      primaryImage: PRIMARY,
      variation: 'wishlist',
    };
    expect(invalid).toBeDefined();
  });

  test('home variation does not accept onRemove (type-only)', () => {
    // Assigned to the narrow per-variation intersection, not the `ZimmProductCardProps` union
    // alias: TypeScript's excess-property check on a *union* target only flags a property as
    // excess when it is unknown to EVERY member, so `onRemove` (valid on the wishlist member)
    // would silently pass here even under `variation: 'home'` if assigned to the union type
    // directly — confirmed empirically while building this test (an earlier version of this
    // exact case, assigned to `ZimmProductCardProps`, produced an "unused @ts-expect-error"
    // compile error because of this). The narrow intersection has no such escape hatch: it is a
    // plain object type with no `onRemove` key anywhere, so the excess property is genuinely
    // unknown and TypeScript reports it.
    //
    // The directive sits directly above the `onRemove` line, not the `const invalid = {` line
    // above it: TS anchors this specific "object literal may only specify known properties"
    // diagnostic to the offending property's own line, and `@ts-expect-error` only suppresses
    // (and only counts as "used" for) a diagnostic reported on the *immediate next* line.
    const invalid: ZimmProductCardBaseProps & ZimmProductCardHomeVariation = {
      id: 'p2',
      href: '/product/1',
      name: 'Dress',
      headingLevel: 'h3',
      primaryImage: PRIMARY,
      variation: 'home',
      // @ts-expect-error — onRemove does not exist on the home variation's own shape.
      onRemove: () => {},
    };
    expect(invalid).toBeDefined();
  });

  test('recentlyViewed variation does not accept onRemove (type-only)', () => {
    // Same reasoning as the `home` case above: assigned to the narrow per-variation
    // intersection, not the `ZimmProductCardProps` union alias, since the union's own weak
    // excess-property check would let `onRemove` (valid on the wishlist member) silently pass
    // here otherwise. `recentlyViewed` adds no fields of its own (see
    // ZimmProductCardRecentlyViewedVariation in index.tsx), so any PLP/Wishlist-only field is
    // equally excess here — `onRemove` is used for direct parity with the `home` case's own test.
    const invalid: ZimmProductCardBaseProps & ZimmProductCardRecentlyViewedVariation = {
      id: 'p4',
      href: '/product/1',
      name: 'Dress',
      headingLevel: 'h3',
      primaryImage: PRIMARY,
      variation: 'recentlyViewed',
      // @ts-expect-error — onRemove does not exist on the recentlyViewed variation's own shape.
      onRemove: () => {},
    };
    expect(invalid).toBeDefined();
  });
});

