describe('ZimmProductCard — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
  test('the stretched-link overlay is unconditional, absolutely positioned, and carries no z-index of its own', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const after = root[STRETCH_KEY] as Record<string, unknown>;
    expect(after.position).toBe('absolute');
    expect(after.inset).toBe(0);
    expect(Object.prototype.hasOwnProperty.call(after, 'zIndex')).toBe(false);
  });

  test('the content-button lift selector uses position:relative + zIndex:1 — that element is not positioned by its own component recipe', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const rule = root[CONTENT_LIFT_KEY] as Record<string, unknown>;
    expect(rule.position).toBe('relative');
    expect(rule.zIndex).toBe(1);
  });

  /**
   * Fix 3 (found during the manual real-browser check performed after the round-2 Scorer PASS):
   * this selector used to be `'[data-card-slot="carousel"] button'` with its own
   * `position: 'relative'` — see the docblock's point 2 for why that shape left the arrows
   * unclickable in a real browser despite this exact test previously passing for it. The fix
   * targets the `carousel` WRAPPER, not the buttons inside it, and (same as `close` below) sets
   * only zIndex — the wrapper is already `position: absolute` via ZimmProductCardMedia's own
   * recipe.
   */
  test('the carousel lift selector sets only zIndex, never position — the wrapper is already positioned by ZimmProductCardMedia’s own recipe', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const carouselLift = root[CAROUSEL_LIFT_KEY] as Record<string, unknown>;
    expect(carouselLift.zIndex).toBe(1);
    expect(Object.prototype.hasOwnProperty.call(carouselLift, 'position')).toBe(false);
  });

  /**
   * Behavioural fix, confirmed against the Jira AC ("when on desktop and the user hovers, then
   * the arrows appear") and live Figma (Carousel is `hidden="true"` on every Default-state
   * instance checked, visible only on the matching Hover-state instance, for both PLP and
   * Wishlist) — see docblock point 6. Unlike every other reveal in this file, this one is NOT
   * gated behind a `ZimmProductCardStyleProps` flag: `baseStyle({})` with no props at all must
   * still emit it, because desktop arrows behave identically across every variation whenever a
   * card has more than one image. `zimmProductCardMedia.css.ts`'s own `carousel` part used to
   * reveal itself unconditionally under its own `[HOVER_CAPABLE_QUERY]` block (a device-
   * CAPABILITY check, making arrows permanently visible on any hover-capable device) — that
   * sub-block is now removed entirely (see that file's own regression guard), so this pair is the
   * only reveal path left for the arrows.
   */
  test('carousel arrows: unconditional hover+focus-visible reveal inside HOVER_CAPABLE_QUERY, present even with no other flags set', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    // Fix J (SFCC-236): `display: 'flex'` is kept here (unlike every other reveal in this file,
    // which drops `display` entirely) — carousel needs it for its own `justifyContent`/
    // `alignItems` layout, since `zimmProductCardMedia.css.ts`'s own unconditional `display: 'none'`
    // is gone. `clipPath: 'none'` is the actual reveal signal now, added alongside it.
    expect((hoverBlock[HOVER_CAROUSEL_KEY] as Record<string, unknown>).display).toBe('flex');
    expect((hoverBlock[HOVER_CAROUSEL_KEY] as Record<string, unknown>).clipPath).toBe('none');
    expect((hoverBlock[FOCUS_VISIBLE_CAROUSEL_KEY] as Record<string, unknown>).display).toBe('flex');
    expect((hoverBlock[FOCUS_VISIBLE_CAROUSEL_KEY] as Record<string, unknown>).clipPath).toBe('none');
  });

  /**
   * Fix J belt-and-braces (SFCC-236) — see zimmProductCard.css.ts docblock point 6's own Fix J
   * note: once the carousel wrapper's hidden state stops being `display: 'none'` (which removed
   * the whole subtree from hit-testing regardless of any descendant's own `pointerEvents`), its
   * arrow buttons' own unconditional `pointerEvents: 'auto'` (zimmProductCardMedia.css.ts's
   * `arrowButton` part) is no longer guaranteed un-hittable while clipped, so this recipe adds an
   * explicit default-off/reveal-on pair targeting the buttons themselves.
   */
  test('carousel arrow buttons: pointerEvents is none by default and auto only once revealed (Fix J belt-and-braces)', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    expect((root[CAROUSEL_BUTTON_LIFT_KEY] as Record<string, unknown>).pointerEvents).toBe('none');
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    expect((hoverBlock[HOVER_CAROUSEL_BUTTON_KEY] as Record<string, unknown>).pointerEvents).toBe('auto');
    expect((hoverBlock[FOCUS_VISIBLE_CAROUSEL_BUTTON_KEY] as Record<string, unknown>).pointerEvents).toBe('auto');
  });

  /**
   * Fix 1 (Scorer rework round 1): the close-button lift rule used to also set
   * `position: 'relative'`, which is what an earlier version of this exact test asserted for all
   * three lift keys together. That was proven wrong by rendering the real composed tree: Media's
   * own `close` recipe part already sets `position: 'absolute', top: 0, right: 0` on this exact
   * element, and this rule's `.css-root [data-card-slot="close"]` descendant+attribute selector
   * has higher specificity than Media's own single-class rule — so `position: 'relative'` here
   * WON the cascade and knocked the remove button out of its pinned top-right corner into normal
   * flow. The element is already positioned (by Media's own recipe), which is all `zIndex` needs
   * to take effect — a competing `position` value here was never necessary. See the DOM-level
   * proof below (real recipes composed through the real `chakra` factory + `getComputedStyle`)
   * for confirmation the fix actually restores the pinned position, not just that this key's shape
   * looks right in isolation.
   */
  test('the close lift selector sets only zIndex, never position — the element is already positioned by ZimmProductCardMedia’s own recipe', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const closeLift = root[CLOSE_LIFT_KEY] as Record<string, unknown>;
    expect(closeLift.zIndex).toBe(1);
    expect(Object.prototype.hasOwnProperty.call(closeLift, 'position')).toBe(false);
  });

  /**
   * Fix I (SFCC-236, found via live mobile-device touch-swipe testing after this branch's own
   * live testing round): the media/gallery scroll region itself was never added to this lift
   * list, even though it is exactly as interactive as the controls nested inside it — a touch
   * swipe starting on the image landed on the invisible overlay `<a>` first, and the real scroll
   * container underneath never received the gesture. Same shape as the close/carousel lift keys
   * above: ZimmProductCardMedia's own root recipe already sets `position: 'relative'`, so only
   * `zIndex` is needed here — plus `cursor: 'pointer'`, since this element is no longer inside the
   * `<a>` that used to convey that affordance via the browser's default link cursor.
   */
  test('the media lift selector sets zIndex and cursor:pointer, never position — the element is already positioned by ZimmProductCardMedia’s own recipe', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const mediaLift = root[MEDIA_LIFT_KEY] as Record<string, unknown>;
    expect(mediaLift.zIndex).toBe(1);
    expect(mediaLift.cursor).toBe('pointer');
    expect(Object.prototype.hasOwnProperty.call(mediaLift, 'position')).toBe(false);
  });

  test('root itself establishes the positioned ancestor the stretched-link overlay resolves against', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    expect((style.root as Record<string, unknown>).position).toBe('relative');
  });

  /**
   * Fix E (full-sweep follow-up audit): price's "hidden by default" half used to be an
   * unconditional root-level rule here — this test asserted exactly that shape before the fix.
   * Moved inside HOVER_CAPABLE_QUERY instead (mirroring notify-me's own Fix C shape), because an
   * unconditional hide left Home's price permanently invisible on a touch pointer (confirmed live:
   * the Home story showed no price at all at mobile widths) — Mobile has no Hover variant at all
   * to ever reveal it. `root[PRICE_KEY]` must now be undefined; the hide lives at
   * `hoverBlock[PRICE_KEY]` instead.
   */
  test('home (hoverRevealsPrice): price has NO unconditional rule (stays visible on touch), hides+reveals only inside HOVER_CAPABLE_QUERY, no size-selector rule at all', () => {
    const style = ZimmProductCardRecipe.baseStyle({ hoverRevealsPrice: true });
    const root = style.root as Record<string, unknown>;
    expect(root[PRICE_KEY]).toBeUndefined();
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    // Fix J (SFCC-236): was `display: 'none'`/`'block'` at all three keys below — hidden/revealed
    // are now expressed via `position`/`clipPath` (see docblock point 3/6's own Fix J note) so a
    // hover-capable pointer that isn't currently hovering/focus-visible still leaves price in the
    // DOM/tab order/accessibility tree, just visually clipped.
    expect((hoverBlock[PRICE_KEY] as Record<string, unknown>).position).toBe('absolute');
    expect((hoverBlock[PRICE_KEY] as Record<string, unknown>).clipPath).toBe('inset(50%)');
    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).position).toBe('static');
    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).clipPath).toBe('none');
    // Fix 2 (Scorer rework round 1): the focus-visible equivalent must reveal identically, so a
    // keyboard-only user tabbing through the card sees the same state a mouse-hover would.
    expect((hoverBlock[FOCUS_VISIBLE_PRICE_KEY] as Record<string, unknown>).position).toBe('static');
    expect((hoverBlock[FOCUS_VISIBLE_PRICE_KEY] as Record<string, unknown>).clipPath).toBe('none');
    expect(root[SIZE_CHIPS_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_VISIBLE_SIZE_CHIPS_KEY]).toBeUndefined();
  });

  test('plp/wishlist (hoverHidesPrice + hoverRevealsSizeSelector): price visible by default, size-selector hidden by default, both swap on hover AND on focus-visible', () => {
    const style = ZimmProductCardRecipe.baseStyle({ hoverHidesPrice: true, hoverRevealsSizeSelector: true });
    const root = style.root as Record<string, unknown>;
    // No unconditional price rule — Content's own natural rendering already shows it by default.
