    // Fix J (SFCC-236) converted this unconditional (outside HOVER_CAPABLE_QUERY) rule from
    // `display: 'none'` to `position`/`clipPath`, on the reasoning that it's the paired hidden
    // state for the hover/focus-visible reveal below it. Fix K (CodeRabbit finding on PR #85,
    // verified correct before fixing) reverted that: unlike price/notify-me's own unconditional
    // rules, THIS one is not scoped to "not yet revealed on a pointer type that CAN reveal it" —
    // it applies on every pointer type, including touch, which never enters HOVER_CAPABLE_QUERY at
    // all. Clip-path here left a real, always-tabbable `<button>` (each ZimmSizeChip's own roving
    // tabindex) permanently reachable by Tab on a touch device with no way to ever reveal it. Back
    // to `display: 'none'` unconditionally; the hover-capable override (asserted just below, on
    // `hoverBlock`) is what now carries the Fix J clip-path technique instead.
    expect(root[SIZE_CHIPS_KEY]).toEqual({ display: 'none' });
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    // Fix K: the hover-capable override — this pointer type genuinely CAN reveal the content
    // below, so it needs the Fix J clip-path technique (stay in the DOM/tab order while not yet
    // revealed) instead of the unconditional display:none above.
    expect((hoverBlock[SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('flex');
    expect((hoverBlock[SIZE_CHIPS_KEY] as Record<string, unknown>).position).toBe('absolute');
    expect((hoverBlock[SIZE_CHIPS_KEY] as Record<string, unknown>).clipPath).toBe('inset(50%)');
    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).position).toBe('absolute');
    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).clipPath).toBe('inset(50%)');
    expect((hoverBlock[HOVER_SIZE_CHIPS_KEY] as Record<string, unknown>).position).toBe('static');
    expect((hoverBlock[HOVER_SIZE_CHIPS_KEY] as Record<string, unknown>).clipPath).toBe('none');
    // Fix 2 (Scorer rework round 1): focus-visible must swap identically to hover — a keyboard
    // user tabbing into the card (e.g. onto the bag button or a size chip) sees the size-selector
    // in place of the price, the same revealed state a mouse-hover produces, not a silently
    // unreachable one.
    expect((hoverBlock[FOCUS_VISIBLE_PRICE_KEY] as Record<string, unknown>).position).toBe('absolute');
    expect((hoverBlock[FOCUS_VISIBLE_PRICE_KEY] as Record<string, unknown>).clipPath).toBe('inset(50%)');
    expect((hoverBlock[FOCUS_VISIBLE_SIZE_CHIPS_KEY] as Record<string, unknown>).position).toBe('static');
    expect((hoverBlock[FOCUS_VISIBLE_SIZE_CHIPS_KEY] as Record<string, unknown>).clipPath).toBe('none');
  });

  test('with every hover flag false/absent, no hover-reveal or focus-visible-reveal rule is emitted at all — a touch/no-hover pointer keeps the natural default permanently', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    expect(root[PRICE_KEY]).toBeUndefined();
    expect(root[SIZE_CHIPS_KEY]).toBeUndefined();
    const hoverBlock = (root[HOVER_CAPABLE_QUERY] ?? {}) as Record<string, unknown>;
    expect(hoverBlock[HOVER_PRICE_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_VISIBLE_PRICE_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_VISIBLE_SIZE_CHIPS_KEY]).toBeUndefined();
  });

  /**
   * Fix C (found during the SFCC-236 Step 6 visual audit): confirmed against the real Figma
   * Default+Hover Unavailable instances for every variation (desktop and mobile) that an
   * out-of-stock item must NOT get the price/size-selector swap, and that the size-chip wrapper
   * stays hidden PERMANENTLY (not just "not swapped in on hover") — index.tsx is responsible for
   * AND-ing `hoverHidesPrice`/`hoverRevealsSizeSelector` with `!isUnavailable`, and separately
   * computing `sizeSelectorUnavailable` to carry that permanent hide, before any of it reaches
   * this recipe. This test passes the exact shape a real `variation: 'plp', isUnavailable: true`
   * card would produce, alongside `hoverRevealsNotifyMe: true` (what `showNotifyMe` resolves to
   * for that same card once `onNotifyMe` is supplied).
   *
   * Fix F (full-sweep follow-up audit) revises this test's own price expectations: it used to
   * assert `root[PRICE_KEY]` was undefined ("price only ever shown via Content's own natural
   * rendering, never touched by this recipe at all"). That was true on Desktop but wrong on
   * Mobile — Figma's Mobile PLP/Wishlist Unavailable references hide price entirely (swapped for
   * notify-me), unlike Desktop's own additive treatment. `sizeSelectorUnavailable` now also
   * carries a mobile-hidden/desktop-shown price rule, asserted below.
   */
  test('unavailable PLP: no desktop price swap, size-chips permanently hidden, price hidden on mobile only, notify-me still hover-gates', () => {
    const style = ZimmProductCardRecipe.baseStyle({
      hoverHidesPrice: false,
      hoverRevealsPrice: false,
      hoverRevealsSizeSelector: false,
      hoverRevealsNotifyMe: true,
      sizeSelectorUnavailable: true,
    });
    const root = style.root as Record<string, unknown>;
    // Both price and size-chips get an unconditional (mobile-first) rule now — a permanent hide
    // for size-chips (no reveal anywhere), and a mobile-only hide for price (reveals again at
    // DESKTOP_QUERY, asserted further below).
    expect((root[PRICE_KEY] as Record<string, unknown>).display).toBe('none');
    expect((root[SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('none');
    expect((root[DESKTOP_QUERY] as Record<string, unknown>)[PRICE_KEY]).toEqual({ display: 'block' });
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    expect(hoverBlock[PRICE_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_PRICE_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_VISIBLE_PRICE_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_VISIBLE_SIZE_CHIPS_KEY]).toBeUndefined();
    // Notify-me's "hidden by default" lives INSIDE the media query (docblock point 4) — never
    // emitted as an unconditional root-level rule, unlike price/size-chips' own unconditional half.
    expect(root[NOTIFY_ME_KEY]).toBeUndefined();
    // Fix J (SFCC-236): all three declarations below were `display: 'none'`/`'block'` — converted
    // together to `position`/`clipPath` (see docblock point 3/6's own Fix J note).
    expect((hoverBlock[NOTIFY_ME_KEY] as Record<string, unknown>).position).toBe('absolute');
    expect((hoverBlock[NOTIFY_ME_KEY] as Record<string, unknown>).clipPath).toBe('inset(50%)');
    expect((hoverBlock[HOVER_NOTIFY_ME_KEY] as Record<string, unknown>).position).toBe('static');
    expect((hoverBlock[HOVER_NOTIFY_ME_KEY] as Record<string, unknown>).clipPath).toBe('none');
    expect((hoverBlock[FOCUS_VISIBLE_NOTIFY_ME_KEY] as Record<string, unknown>).position).toBe('static');
    expect((hoverBlock[FOCUS_VISIBLE_NOTIFY_ME_KEY] as Record<string, unknown>).clipPath).toBe('none');
  });

  test('hoverRevealsNotifyMe absent/false emits no notify-me rule at all — matches an in-stock card, where notify-me never mounts', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    expect(root[NOTIFY_ME_KEY]).toBeUndefined();
    const hoverBlock = (root[HOVER_CAPABLE_QUERY] ?? {}) as Record<string, unknown>;
    expect(hoverBlock[NOTIFY_ME_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_NOTIFY_ME_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_VISIBLE_NOTIFY_ME_KEY]).toBeUndefined();
  });

  /**
   * Fix D (found during the SFCC-236 Step 6 visual audit): PLP's Mobile Card-content instance
   * has the bag icon hidden — confirmed via `get_metadata` on node 40002163:41479 (`Icons` frame
   * `hidden="true"`), unlike Desktop and unlike Wishlist's own Mobile instance (40002187:58472,
   * no `hidden` attribute at all). `DESKTOP_QUERY` is a viewport-width gate (`min-width`), a
   * genuinely different axis from `HOVER_CAPABLE_QUERY` above.
   */
  test('hideBagOnMobile: hidden by default, shown again (as flex, not block) from DESKTOP_QUERY up', () => {
    const style = ZimmProductCardRecipe.baseStyle({ hideBagOnMobile: true });
    const root = style.root as Record<string, unknown>;
    expect((root[BAG_KEY] as Record<string, unknown>).display).toBe('none');
    const desktopBlock = root[DESKTOP_QUERY] as Record<string, unknown>;
    // 'flex', not 'block' — ZimmProductCardContent's own bagWrapper part uses flex to centre the
    // icon; 'block' would silently flatten that centring rather than merely fail to apply, since
    // this selector's specificity beats Content's own single class either way.
    expect((desktopBlock[BAG_KEY] as Record<string, unknown>).display).toBe('flex');
  });

  test('hideBagOnMobile absent/false emits no bag-visibility rule at all — matches Home (never shows the bag) and Wishlist (shows it on every breakpoint)', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    expect(root[BAG_KEY]).toBeUndefined();
    // [DESKTOP_QUERY] itself is always present (mirrors [HOVER_CAPABLE_QUERY]'s own unconditional
    // presence, asserted with the same `?? {}` fallback elsewhere in this file) — it's the BAG_KEY
    // entry inside it that must be absent when nothing needs a desktop reveal.
    const desktopBlock = (root[DESKTOP_QUERY] ?? {}) as Record<string, unknown>;
    expect(desktopBlock[BAG_KEY]).toBeUndefined();
  });

  /**
   * Regression test for a real bug this exact combination caused: `sizeSelectorUnavailable` and
   * `hideBagOnMobile` used to each spread their own separate `[DESKTOP_QUERY]` object into `root`
   * — a plain object spread doesn't deep-merge two spreads sharing a key, so whichever one came
   * last silently overwrote the other's `[DESKTOP_QUERY]` value entirely. Confirmed for real in a
   * live browser: an unavailable PLP card's price stayed `display: none` at desktop width even
   * though `window.matchMedia('(min-width: 48em)').matches` correctly reported `true` — every
   * existing jsdom test still passed at the time, because none of them set BOTH flags at once,
   * which is exactly the shape a real unavailable PLP card produces (PLP's own
   * `hideBagOnMobile: true` combined with `sizeSelectorUnavailable: true` once it's out of stock).
   * This test passes that exact realistic combination and checks BOTH rules survive together in
   * the one shared `[DESKTOP_QUERY]` block.
   */
  test('sizeSelectorUnavailable and hideBagOnMobile together (the real unavailable-PLP shape) both survive in the same shared [DESKTOP_QUERY] block', () => {
    const style = ZimmProductCardRecipe.baseStyle({ sizeSelectorUnavailable: true, hideBagOnMobile: true });
    const root = style.root as Record<string, unknown>;
    const desktopBlock = root[DESKTOP_QUERY] as Record<string, unknown>;
    expect((desktopBlock[PRICE_KEY] as Record<string, unknown>).display).toBe('block');
    expect((desktopBlock[BAG_KEY] as Record<string, unknown>).display).toBe('flex');
  });
});

